with scored as (select *, last_value(city) ignore nulls over (partition by country order by rating, id rows between unbounded preceding and current row) as last_known_city, row_number() over (partition by city order by rating desc, id) as seq_no, row_number() over (partition by city order by rating, id) as row_seq, avg(rating) over (partition by country order by rating, id rows between 2 preceding and 1 preceding) as rating_avg_2_prior from suppliers) select id, city, rating, last_known_city, seq_no, row_seq, rating_avg_2_prior from scored;
